SELECT 
  FROM rpt01_daily
 WHERE 1=1
   AND rpt01_company_id = #{companyId}
   AND rpt01_person_id  = #{personId}
   AND rpt01_date BETWEEN #{startDate}::date AND #{closeDate}::date
   AND CONCAT(rpt01_content, rpt01_note) ILIKE #{searchText}
 ORDER BY rpt01_date DESC, rpt01_content

SELECT 
  FROM rpt01_daily
 WHERE rpt01_daily_id   = #{dailyId}
   AND rpt01_company_id = #{companyId}

